167	/** `git submodule status` lines as {path, initialised}; a path may contain spaces. */
168	export function parseSubmoduleStatus(listing: string): Array<{ path: string; initialised: boolean }> {
169	  const found: Array<{ path: string; initialised: boolean }> = [];
170	  for (const line of listing.split("\n")) {
171	    const match = /^(.)[0-9a-f]{40,64} (.*?)(?: \(.*\))?$/.exec(line);
172	    if (match) found.push({ path: match[2], initialised: match[1] !== "-" });
173	  }
174	  return found;
175	}
