40	/** Rewrites the worktree's `.git` pointer to a repository planted INSIDE the worktree whose config runs `marker`-writing commands. */
41	function plantRepository(f: ReturnType<typeof fixture>, branch: string, config: string[]): string {
42	  const marker = path.join(f.root, "MARKER");
43	  const plant = path.join(f.dir, "plant");
44	  fs.mkdirSync(plant);
45	  git(plant, "init", "-q", "-b", "main");
46	  git(plant, "config", "user.email", "t@example.com");
47	  git(plant, "config", "user.name", "T");
48	  fs.writeFileSync(path.join(plant, "seed"), "seed\n");
49	  git(plant, "add", "seed");
50	  git(plant, "-c", "commit.gpgsign=false", "commit", "-q", "-m", "seed");
51	  git(plant, "branch", branch);
52	  git(plant, "worktree", "add", "-q", "-b", `${branch}-wt`, path.join(f.root, "planted-wt"));
53	  const admin = path.join(plant, ".git", "worktrees", "planted-wt");
54	  fs.writeFileSync(path.join(admin, "gitdir"), path.join(f.dir, ".git") + "\n");
55	  fs.writeFileSync(path.join(admin, "HEAD"), `ref: refs/heads/${branch}\n`);
56	  for (const line of config) git(plant, "config", ...line.replace("@MARKER@", marker).split("\u0000"));
57	  fs.writeFileSync(path.join(f.dir, ".git"), `gitdir: ${admin}\n`);
58	  fs.writeFileSync(path.join(f.dir, ".gitattributes"), "* filter=plant\n");
59	  fs.writeFileSync(path.join(f.dir, "a.txt"), "edited by the agent\n");
60	  return marker;
61	}
